CREATE TABLE runtime_configs (
  id BIGINT NOT NULL AUTO_INCREMENT COMMENT 'Agent Runtime执行配置主键', project_id BIGINT NOT NULL COMMENT '所属项目主键', status VARCHAR(32) NOT NULL DEFAULT 'UNCONFIGURED' COMMENT '授权状态：UNCONFIGURED、PENDING_APPROVAL、APPROVED或EXPIRED', model_ref VARCHAR(128) NULL COMMENT '获批模型引用', tool_refs JSON NULL COMMENT '获批工具范围', operation_refs JSON NULL COMMENT '获批操作权限范围', secret_ref VARCHAR(512) NULL COMMENT '外部密钥库引用，不返回给客户端', approved_by_ref CHAR(36) NULL COMMENT '配置批准人主体UUID', approved_at DATETIME(3) NULL COMMENT '配置批准时间', expires_at DATETIME(3) NULL COMMENT '配置失效时间', created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '配置创建时间', updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '配置更新时间',
  PRIMARY KEY(id), UNIQUE KEY uk_runtime_config_project(project_id), CONSTRAINT fk_runtime_config_project FOREIGN KEY(project_id) REFERENCES projects(id), CONSTRAINT fk_runtime_config_approver FOREIGN KEY(approved_by_ref) REFERENCES principals(principal_ref)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Agent Runtime授权配置状态';
